    97	const LOYALTY_DISCOUNT = 0.2;
    98	const LOYALTY_YEARS = 2;
    99	
   100	function isLongStanding(customer: Customer): boolean {
   101	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
   102	}
   103	
   104	// A discount, so it enters the policy-scoped rate as a negative rate.
   105	function loyaltyRate(customer: Customer): number {
   106	  return isLongStanding(customer) ? -LOYALTY_DISCOUNT : 0;
   107	}
   108	
   109	const FOLLOW_UP_DISCOUNT = 0.15;
   110	
   111	// Every contract after the customer's first earns the follow-up discount.
   112	function followUpRate(previousContracts: number): number {
   113	  return previousContracts > 0 ? -FOLLOW_UP_DISCOUNT : 0;
   114	}
   115	
   116	// The MHPCO's policy-scoped tariff: each recognised policy-wide modifier contributes
   117	// its own rate, and the rates are assessed together against the policy base premium.
   118	function policyScopedRate(customer: Customer, previousContracts: number): number {
   119	  return FIRST_INSURANCE_SURCHARGE + loyaltyRate(customer) + followUpRate(previousContracts);
   120	}
   121	
   122	// Policy-scoped modifiers are assessed against the policy base premium alone -- the
   123	// plain sum of the item base premiums, deliberately excluding item-scoped surcharges.
   124	function policyScopedAdjustment(
   125	  basePremium: number,
   126	  customer: Customer,
   127	  previousContracts: number,
   128	): number {
   129	  return basePremium * policyScopedRate(customer, previousContracts);
   130	}
   131	
   132	export function quote(customer: Customer, items: Item[], previousContracts: number): number {
   133	  const basePremium = policyBasePremium(items);
   134	  const modifiedPremium =
   135	    basePremium + itemScopedSurcharges(items) + policyScopedAdjustment(basePremium, customer, previousContracts);
   136	  return roundUpInMHPCOFavor(modifiedPremium + PROCESSING_FEE);
   137	}
